// The favicons of the two backends a browser can land on: api.intentic.dev (blue) and a sandbox's own address (green).
// Both answer JSON, so there is no page to carry a <link rel="icon">; the browser asks for /favicon.ico by convention,
// and each serves the ICO written here from a generated module. Same lotus as the site's icon (`lotus.mjs`), only the
// tint differs. Committed output, run when the mark or a tint changes: node _site/site/scripts/backend-icons.mjs
import { writeFile } from "node:fs/promises";
import { join } from "node:path";

import { repoRoot } from "@intentic/constants/node";
import sharp from "sharp";

import { API_BLUE, buildIco, icon, petals, SANDBOX_GREEN } from "./lotus.mjs";

const ROOT = repoRoot(import.meta.url);
const ICO_SIZES = [16, 32, 48];

const TARGETS = [
    { fill: API_BLUE, out: "_platform/api/src/probe/favicon.generated.ts", who: "api.intentic.dev" },
    { fill: SANDBOX_GREEN, out: "_sandbox/sandbox/src/system/boot/favicon.generated.ts", who: "a sandbox's own address" },
];

const paths = petals();

for (const { fill, out, who } of TARGETS) {
    const images = await Promise.all(
        ICO_SIZES.map(async (size) => ({
            size,
            data: await sharp(Buffer.from(icon(size, paths, fill)))
                .png({ compressionLevel: 9 })
                .toBuffer(),
        })),
    );
    const ico = buildIco(images);
    const source = [
        `// Generated by _site/site/scripts/backend-icons.mjs; do not edit. The favicon of ${who}: the lotus in ${fill},`,
        `// an ICO of ${ICO_SIZES.join("/")}px PNGs, base64.`,
        `export const FAVICON_ICO_BASE64 = "${ico.toString("base64")}";`,
        ``,
    ].join("\n");
    await writeFile(join(ROOT, out), source);
    console.log(`${out}  ${(ico.length / 1024).toFixed(1)} KB`);
}
